sys_script_client.script:
/** * ESR - Validate category and subcategory on submit * * A deliberately synchronous, last-line check before the form is submitted. * * It only tests what can be evaluated from the form itself with no server * round trip: a Subcategory selected while Category is empty. The full * relationship check needs the subcategory's own category, which requires a * server lookup, and is performed by the "ESR - Validate category and * subcategory" business rule. * * This script intentionally does NOT use the async-GlideAjax-then-resubmit * pattern. Re-submitting the form from a callback would discard the UI action * that initiated the save, which would break the Accept / Put On Hold / * Resume Work / Resolve / Request Reopen / Close Ticket workflow buttons. */ function onSubmit() { var category = g_form.getValue('category') var subcategory = g_form.getValue('subcategory')
if (subcategory && !category) { g_form.addErrorMessage( 'Select a Category that matches the chosen Subcategory before submitting.' ) return false }
return true }
